sql_calls.sql:
SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT * FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01'
  AND complaint_ts <= '2026-06-30';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'pos_payments';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'psp_upi_report';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'forecasts';

SELECT COUNT(*) as total_shipments,
       COUNT(CASE WHEN slot_start >= '2026-07-01' AND slot_start < '2026-09-01' THEN 1 END) as jul_aug_shipments
FROM warehouse.shipments;

SELECT COUNT(DISTINCT order_id) as distinct_orders
FROM store.store_orders
WHERE order_ts >= '2026-06-01' AND order_ts < '2026-07-01';

SELECT COUNT(DISTINCT order_id) as distinct_orders
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT COUNT(*) as total_bills, COUNT(DISTINCT bill_id) as distinct_bills
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT COUNT(*) as total_attempts, COUNT(DISTINCT bill_id) as distinct_bills
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT COUNT(*) as sales_count, SUM(qty) as total_qty
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01' AND sku_scanned = 'ATTA-WW-5KG';

SELECT COUNT(*) as sales_count, SUM(qty) as total_qty
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01' AND sku_scanned = 'MILK-TONED-500ML';

SELECT SUM(units) as total_units, SUM(revenue) as total_revenue
FROM store.daily_sales
WHERE sku = 'MILK-TONED-500ML' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT SUM(units_sold) as total_units, SUM(revenue_inr) as total_revenue
FROM store.daily_sales
WHERE sku = 'MILK-TONED-500ML' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT SUM(revenue_inr) as total_revenue
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date < '2026-07-01';

SELECT COUNT(*) AS refund_count
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT rrn, initiated_ts, amount_inr, status, bill_ref
FROM payments.psp_upi_report
LIMIT 20;

SELECT DISTINCT tender
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sku, gtin, name, pack
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT SUM(net_inr) AS total_net_upi_june
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) AS total_bills_june
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT sku, gtin, name, pack, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT COUNT(*) as payment_attempts_june
FROM payments.pos_payments
WHERE bill_id LIKE 'B2606%';

